using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
using System.Xml.Linq;
using Knx;

var directory = Path.Combine(Path.GetTempPath(), "opencode", "buschord-archive-" + Guid.NewGuid().ToString("N"));
Directory.CreateDirectory(directory);
int checks = 0;
try
{
    // Independent source fixture, not generated by the serializer under test.
    const string fixture = """
        <KNX xmlns="http://knx.org/xml/project/23" xmlns:v="urn:vendor" created-by="fixture" v:root="keep">
          <!--retain comment--><MasterData Id="MD-1" Version="198" Signature="signature"/>
          <Project Id="P-1" Name="Original" Comment="project comment" v:project="keep">
            <AddinData Id="M0083-A0041">AQIDBAU=</AddinData>
            <v:Building Name="opaque"><v:Room/></v:Building>
            <Installations><Installation InstallationId="I-7" Name="House" Type="Regular">
              <Topology><Area Id="area-id" Address="1" Name="Area" v:area="keep">
                <Line Id="line-id" Address="1" Name="Line" MediumTypeRefId="MT-0">
                  <DeviceInstance Id="device-id" Address="1.1.1" ProductRefId="M-0001_P-1" Name="Device" Comment="device comment" v:device="keep">
                    <AddinData Id="M0083-A0096">BwAq</AddinData>
                    <ParameterInstanceRefs><ParameterInstanceRef RefId="native-opaque" Value="17" v:flag="keep"/></ParameterInstanceRefs>
                    <v:Payload><v:Value>opaque text</v:Value></v:Payload>
                    <ComObjectInstanceRefs v:container="keep"><ComObjectInstanceRef RefId="O-1" Links="GA-1" v:object="keep"/></ComObjectInstanceRefs>
                    <Channels><ChannelInstance Id="channel-id" Name="Channel"><ChannelInstance Id="subchannel-id" Name="Subchannel"/></ChannelInstance></Channels>
                  </DeviceInstance>
                  <Segment Id="segment-id" Address="0" Name="Segment"/>
                </Line>
              </Area></Topology>
              <GroupAddresses><GroupRanges><GroupRange Id="GR-1" Name="Main" RangeStart="0" RangeEnd="2047">
                <GroupAddress Id="GA-1" Address="0/0/1" Name="Light" Comment="group comment" Puid="7" v:address="keep"/>
              </GroupRange></GroupRanges></GroupAddresses>
            </Installation></Installations>
          </Project>
        </KNX>
        """;
    var baggage = new byte[] { 0, 255, 17, 0, 42 };
    foreach (bool nested in new[] { false, true })
    {
        var originalPath = Path.Combine(directory, nested ? "nested.knxproj" : "root.knxproj");
        var parts = new Dictionary<string, byte[]>
        {
            ["0.xml"] = Encoding.UTF8.GetBytes(fixture),
            ["unknown/part.bin"] = baggage,
            ["../never-extracted.txt"] = baggage,
        };
        File.WriteAllBytes(originalPath, nested
            ? Zip(new() { ["P-1.zip"] = Zip(parts), ["M-0001/product.xml"] = baggage, ["knx_master.xml"] = baggage })
            : Zip(parts.Concat(new Dictionary<string, byte[]> { ["M-0001/product.xml"] = baggage }).ToDictionary()));
        var untouched = File.ReadAllBytes(originalPath);
        var project = Knxproj.Load(originalPath);
        var device = Device(project);
        Check(device.Id == "device-id" && project.Installations[0].Areas[0].Id == "area-id", "loaded IDs");
        Check(device.Channels.Single().Channels.Single().Id == "subchannel-id", "loaded channels");
        Check(project.Installations[0].MainRanges[0].Addresses[0].Comment == "group comment", "loaded comments");
        device.ParameterValues["PR-1"] = "one & <two>";
        device.ComObjectRefs[0].Number = 9;
        project.Name = "Saved As";
        var undo = new UndoStack();
        undo.Reset(project);
        device.ParameterValues["PR-1"] = "changed";
        project.Name = "Changed";
        undo.Push(project);
        var undone = undo.Undo()!;
        Check(undone.Name == "Saved As" && Device(undone).ParameterValues["PR-1"] == "one & <two>", "undo parameter/name");
        var redone = undo.Redo()!;
        Check(redone.Name == "Changed" && Device(redone).ParameterValues["PR-1"] == "changed", "redo parameter/name");
        foreach (var state in new[] { undone, redone })
        {
            var saveAs = Path.Combine(directory, $"{nested}-{state.Name}.knxproj");
            Knxproj.Save(state, saveAs);
            Check(File.ReadAllBytes(originalPath).SequenceEqual(untouched), "SaveAs leaves source unchanged");
            var savedParts = Unzip(File.ReadAllBytes(saveAs));
            Check(savedParts["M-0001/product.xml"].SequenceEqual(baggage), "outer product retained after undo/redo");
            var projectParts = nested ? Unzip(savedParts["P-1.zip"]) : savedParts;
            Check(projectParts["unknown/part.bin"].SequenceEqual(baggage) && projectParts["../never-extracted.txt"].SequenceEqual(baggage), "arbitrary parts retained without extraction");
            using var xmlInput = new MemoryStream(projectParts["0.xml"]);
            var doc = XDocument.Load(xmlInput);
            var vendor = (XNamespace)"urn:vendor";
            Check(doc.Descendants(vendor + "Value").Single().Value == "opaque text", "unknown XML element");
            Check(doc.Descendants().Single(e => e.Name.LocalName == "DeviceInstance").Attribute(vendor + "device")?.Value == "keep", "unknown XML attribute");
            Check(doc.Descendants().Single(e => e.Name.LocalName == "ParameterInstanceRef" && e.Name.NamespaceName == Knxproj.ProjectNamespace).Attribute("Value")?.Value == "17", "native parameters retained opaque");
            Check(doc.DescendantNodes().OfType<XComment>().Any(c => c.Value == "retain comment"), "XML comments retained");
            var addinData = doc.Descendants().Where(e => e.Name.LocalName == "AddinData").ToList();
            Check(addinData.Count == 2 &&
                  addinData.Any(e => (string?)e.Attribute("Id") == "M0083-A0041" && e.Value == "AQIDBAU=") &&
                  addinData.Any(e => (string?)e.Attribute("Id") == "M0083-A0096" && e.Value == "BwAq"),
                "AddinData retained after undo/redo: " +
                string.Join("; ", addinData.Select(e => $"{e.Attribute("Id")?.Value}={e.Value}")));
            Check((string?)doc.Root!.Attribute("created-by") == "fixture", "original producer retained");
            var reloaded = Knxproj.Load(saveAs);
            Check(Device(reloaded).ParameterValues["PR-1"] == Device(state).ParameterValues["PR-1"], "parameter roundtrip");
            Check(Device(reloaded).ComObjectRefs[0].Number == 9, "object number roundtrip");
            Check(reloaded.MasterData.Signature == "signature" && reloaded.Installations[0].Type == InstallationType.Regular, "other model state");
            Check(Device(reloaded).Channels.Single().Id == "channel-id" && Device(reloaded).Comment == "device comment", "channels/comments roundtrip");
            reloaded.Name = "In place";
            Knxproj.Save(reloaded, saveAs);
            Check(Knxproj.Load(saveAs).Name == "In place", "atomic in-place replacement");
        }

        // Refusal during serialization must not touch an existing destination.
        device.ParameterValues["bad"] = "\u0001";
        ExpectFailure(() => Knxproj.Save(project, originalPath), "invalid XML refuses save");
        Check(File.ReadAllBytes(originalPath).SequenceEqual(untouched), "serialization failure leaves destination identical");
        device.ParameterValues.Remove("bad");
        // Windows refuses to replace an open file; Unix allows it, so this check is Windows-only.
        if (OperatingSystem.IsWindows())
        {
            using var locked = new FileStream(originalPath, FileMode.Open, FileAccess.Read, FileShare.Read);
            ExpectFailure(() => Knxproj.Save(project, originalPath), "locked destination refuses atomic replace");
            Check(File.ReadAllBytes(originalPath).SequenceEqual(untouched), "replace failure leaves destination identical");
        }
        else
        {
            Console.WriteLine("  SKIP locked destination (Unix allows replacing an open file)");
        }
        Check(!Directory.EnumerateFiles(directory, "*.tmp").Any(), "failed save cleans temporary file");
    }

    var freshPath = Path.Combine(directory, "fresh.knxproj");

    var interleavedXml = XDocument.Parse(fixture);
    XNamespace fixtureNs = Knxproj.ProjectNamespace;
    var interleavedObjects = interleavedXml.Descendants(fixtureNs + "ComObjectInstanceRefs").Single();
    interleavedObjects.Add(new XComment("between native references"), new XElement(fixtureNs + "ComObjectInstanceRef", new XAttribute("RefId", "O-2")));
    var interleavedPath = Path.Combine(directory, "interleaved.knxproj");
    File.WriteAllBytes(interleavedPath, Zip(new() { ["0.xml"] = Encoding.UTF8.GetBytes(interleavedXml.ToString()) }));
    var interleaved = Knxproj.Load(interleavedPath); interleaved.Name = "Opaque slots retained";
    Knxproj.Save(interleaved, interleavedPath);
    Check(ReferenceSlots(interleavedPath).SequenceEqual(new[] { "O-1", "between native references", "O-2" }), "opaque comments stay between modeled references on save");
    Device(interleaved).ComObjectRefs.RemoveAt(0); Knxproj.Save(interleaved, interleavedPath);
    Check(ReferenceSlots(interleavedPath).SequenceEqual(new[] { "between native references", "O-2" }), "deleting a modeled reference retains opaque sibling placement");

    static IEnumerable<string> ReferenceSlots(string path)
    {
        using var stream = new MemoryStream(Unzip(File.ReadAllBytes(path))["0.xml"]);
        return XDocument.Load(stream).Descendants().Single(e => e.Name.LocalName == "ComObjectInstanceRefs").Nodes()
            .Select(n => n is XElement e ? (string?)e.Attribute("RefId") : n is XComment c ? c.Value : null).OfType<string>().ToList();
    }
    var fresh = new Project { Id = "P-new", Name = "New" };
    Knxproj.Save(fresh, freshPath);
    Check(Unzip(File.ReadAllBytes(freshPath)).ContainsKey("0.xml") && Knxproj.Load(freshPath).Name == "New", "new projects use root 0.xml");

    var unsupported = Path.Combine(directory, "unsupported.knxproj");
    foreach (var bytes in new[]
    {
        Zip(new() { ["other.xml"] = Encoding.UTF8.GetBytes(fixture) }),
        Zip(new() { ["0.xml"] = Encoding.UTF8.GetBytes(fixture.Replace("project/23", "project/99")) }),
        Zip(new() { ["0.xml"] = Encoding.UTF8.GetBytes("<!DOCTYPE KNX [<!ENTITY x SYSTEM 'file:///never'>]><KNX>&x;</KNX>") }),
        Zip(new() { ["0.xml"] = Encoding.UTF8.GetBytes(new string(' ', 16 * 1024 * 1024 + 1)) }),
        Zip(new() { ["0.xml"] = Encoding.UTF8.GetBytes("<x>" + string.Concat(Enumerable.Repeat("<x>", 130)) + string.Concat(Enumerable.Repeat("</x>", 130)) + "</x>") }),
        Encrypted(Zip(new() { ["0.xml"] = Encoding.UTF8.GetBytes(fixture) })),
        Zip(new() { ["P-1.zip"] = Encrypted(Zip(new() { ["0.xml"] = Encoding.UTF8.GetBytes(fixture) })) }),
        Zip(new() { ["0.xml"] = Encoding.UTF8.GetBytes(fixture), ["P-1.zip"] = Zip(new() { ["0.xml"] = Encoding.UTF8.GetBytes(fixture) }) }),
    })
    {
        File.WriteAllBytes(unsupported, bytes);
        ExpectFailure(() => Knxproj.Load(unsupported), "unsupported/bounded input rejected");
        Check(File.ReadAllBytes(unsupported).SequenceEqual(bytes), "unsupported input remains identical");
    }

    var appPath = Path.Combine(directory, "application.knxproj");
    File.WriteAllBytes(appPath, Zip(new()
    {
        ["0.xml"] = Encoding.UTF8.GetBytes(fixture),
        ["M-0001/M-0001_A-0001.xml"] = Encoding.UTF8.GetBytes("<ApplicationProgram Name='retained'/>")
    }));
    Check((string?)Knxproj.LoadApplicationProgram(appPath, "M-0001_A-0001")?.Root?.Attribute("Name") == "retained", "application program caller uses bounded archive reader");
    var largeApplicationPath = Path.Combine(directory, "large-application.knxproj");
    File.WriteAllBytes(largeApplicationPath, Zip(new()
    {
        ["0.xml"] = Encoding.UTF8.GetBytes(fixture),
        ["M-0001/M-0001_A-large.xml"] = Encoding.UTF8.GetBytes("<ApplicationProgram><!--" + new string('x', 65 * 1024 * 1024) + "--></ApplicationProgram>")
    }));
    Check(Knxproj.LoadApplicationProgram(largeApplicationPath, "M-0001_A-large") is not null,
        "manufacturer applications have a separate bounded size budget from project XML");
    var largeRoundtrip = Path.Combine(directory, "large-application-roundtrip.knxproj");
    Knxproj.Save(Knxproj.Load(largeApplicationPath), largeRoundtrip);
    Check(Knxproj.LoadApplicationProgram(largeRoundtrip, "M-0001_A-large")?.Root?.FirstNode is XComment largeComment
        && largeComment.Value.Length == 65 * 1024 * 1024, "application above 64 MiB survives the bounded archive rewrite");
    var mismatchedApplication = Path.Combine(directory, "mismatched-application.knxproj");
    using (var sourceArchive = ZipFile.OpenRead(largeApplicationPath))
    using (var targetArchive = ZipFile.Open(mismatchedApplication, ZipArchiveMode.Create))
        foreach (var entry in sourceArchive.Entries)
        {
            using var sourceEntry = entry.Open();
            using var targetEntry = targetArchive.CreateEntry(entry.FullName.Replace("M-0001/", "M-0002/", StringComparison.Ordinal)).Open();
            sourceEntry.CopyTo(targetEntry);
        }
    ExpectFailure(() => Knxproj.Load(mismatchedApplication), "mismatched manufacturer path does not acquire the larger application budget");
    var linkedAppPath = Path.Combine(directory, "hardware-application.knxproj");
    var nativeParameters = XDocument.Parse(fixture);
    var nativeDevice = nativeParameters.Descendants().First(e => e.Name.LocalName == "DeviceInstance");
    var nativeNs = nativeDevice.Name.Namespace;
    nativeDevice.Element(nativeNs + "ParameterInstanceRefs")!.Add(
        new XElement(nativeNs + "ParameterInstanceRef", new XAttribute("RefId", "native-ref"), new XAttribute("Value", "42")));
    File.WriteAllBytes(linkedAppPath, Zip(new()
    {
        ["0.xml"] = Encoding.UTF8.GetBytes(nativeParameters.ToString()),
        ["M-0001/Hardware.xml"] = Encoding.UTF8.GetBytes("""
            <KNX><Hardware Id="M-0001_H-test" Name="Hardware">
              <Products><Product Id="M-0001_H-test_P-test" Text="Product label" /></Products>
              <Hardware2Programs><Hardware2Program Id="M-0001_H-test_HP-0001">
                <ApplicationProgramRef RefId="M-0001_A-0001" />
              </Hardware2Program></Hardware2Programs>
            </Hardware></KNX>
            """),
        ["M-0001/M-0001_A-0001.xml"] = Encoding.UTF8.GetBytes("<ApplicationProgram Name='linked'/>")
    }));
    Check((string?)Knxproj.LoadApplicationProgram(linkedAppPath, "M-0001_H-test_HP-0001")?.Root?.Attribute("Name") == "linked",
        "hardware program references resolve through Hardware.xml");
    var linkedProject = Knxproj.Load(linkedAppPath);
    Check(Device(linkedProject).ParameterValues.GetValueOrDefault("native-ref") == "42", "native parameter overrides are imported");
    Check(linkedProject.Hardware["M-0001_H-test_P-test"].Name == "Product label", "product-specific display text is retained");
    var parameterEdit = Device(linkedProject);
    parameterEdit.ParameterValues["native-ref"] = "43";
    var editedParameterProject = Knxproj.FromXml(Knxproj.ToXml(linkedProject));
    Check(Device(editedParameterProject).ParameterValues["native-ref"] == "43", "local parameter edits override retained native values on reload");
    var duplicateParameters = new XDocument(nativeParameters);
    duplicateParameters.Descendants(nativeNs + "ParameterInstanceRefs").First().Add(
        new XElement(nativeNs + "ParameterInstanceRef", new XAttribute("RefId", "native-ref"), new XAttribute("Value", "0")));
    ExpectFailure(() => Knxproj.FromXml(duplicateParameters), "duplicate native parameter references are rejected");
    var ambiguousAppPath = Path.Combine(directory, "ambiguous-application.knxproj");
    var ambiguousParts = Unzip(File.ReadAllBytes(linkedAppPath));
    ambiguousParts["M-0001/Hardware.xml"] = Encoding.UTF8.GetBytes(Encoding.UTF8.GetString(ambiguousParts["M-0001/Hardware.xml"])
        .Replace("<ApplicationProgramRef RefId=\"M-0001_A-0001\" />", "<ApplicationProgramRef RefId=\"M-0001_A-0001\" /><ApplicationProgramRef RefId=\"M-0001_A-0002\" />"));
    File.WriteAllBytes(ambiguousAppPath, Zip(ambiguousParts));
    Check(Knxproj.LoadApplicationProgram(ambiguousAppPath, "M-0001_H-test_HP-0001") is null,
        "ambiguous hardware application versions are never guessed");
    var applicationProject = Knxproj.Load(appPath);
    var applicationSaveAs = Path.Combine(directory, "application-copy.knxproj");
    Knxproj.Save(applicationProject, applicationSaveAs);
    Check((string?)Knxproj.LoadApplicationProgram(applicationSaveAs, "M-0001_A-0001")?.Root?.Attribute("Name") == "retained", "application program readable after SaveAs");

    var editable = Knxproj.FromXml(XDocument.Parse(fixture));
    var editedDevice = Device(editable);
    editedDevice.Address = IndividualAddress.Parse("1.1.9");
    editedDevice.Comment = null;
    editedDevice.ComObjectRefs[0].Links.Clear();
    editedDevice.Channels.Clear();
    var editedXml = Knxproj.ToXml(editable);
    var edited = Knxproj.FromXml(editedXml);
    Check(Device(edited).Id == "device-id" && Device(edited).Address.ToString() == "1.1.9", "edit address preserves stable ID");
    Check(Device(edited).Comment is null && Device(edited).ComObjectRefs[0].Links.Count == 0 && Device(edited).Channels.Count == 0, "remove modeled values");
    Check(editedXml.Descendants((XNamespace)"urn:vendor" + "Payload").Any(), "edits preserve unknown content");
    editable.Installations[0].Areas[0].Lines[0].Devices.Clear();
    Check(!Knxproj.ToXml(editable).Descendants().Any(e => e.Name.LocalName == "DeviceInstance"), "modeled deletion persists");

    var emptyRefs = Knxproj.FromXml(XDocument.Parse(fixture));
    Device(emptyRefs).ComObjectRefs.Clear();
    var emptyXml = Knxproj.ToXml(emptyRefs);
    Check(emptyXml.Descendants().Single(e => e.Name.LocalName == "ComObjectInstanceRefs").Attribute((XNamespace)"urn:vendor" + "container")?.Value == "keep", "clearing collection preserves vendor container attributes");
    Check(Device(Knxproj.FromXml(emptyXml)).ComObjectRefs.Count == 0, "empty reference collection roundtrip");

    var relocated = Knxproj.FromXml(XDocument.Parse(fixture));
    var relocatedDevice = Device(relocated);
    var area = relocated.Installations[0].Areas[0];
    area.Lines[0].Devices.Remove(relocatedDevice);
    var newLine = new Line { Id = "L-new", Address = 2, Name = "New line" };
    newLine.Devices.Add(relocatedDevice);
    area.Lines.Add(newLine);
    var relocatedXml = Knxproj.ToXml(relocated);
    Check(relocatedXml.Descendants((XNamespace)"urn:vendor" + "Payload").Count() == 1, "moving device into new parent preserves opaque XML");
    Check(Knxproj.FromXml(relocatedXml).Installations[0].Areas[0].Lines[1].Devices.Single().Id == "device-id", "move persists");

    var reorderedXml = XDocument.Parse(fixture);
    var rangeXml = reorderedXml.Descendants().Single(e => e.Name.LocalName == "GroupRange");
    var secondAddress = new XElement(rangeXml.Elements().Single());
    secondAddress.SetAttributeValue("Id", "GA-2");
    secondAddress.SetAttributeValue("Address", "0/0/2");
    rangeXml.Add(secondAddress);
    var reordered = Knxproj.FromXml(reorderedXml);
    reordered.Installations[0].MainRanges[0].Addresses.Reverse();
    Check(Knxproj.FromXml(Knxproj.ToXml(reordered)).Installations[0].MainRanges[0].Addresses[0].Id == "GA-2", "modeled order persists");

    var ambiguous = Knxproj.FromXml(XDocument.Parse(fixture));
    ambiguous.Installations[0].Areas[0].Lines[0].Devices.Add(new DeviceInstance { Id = "device-id", ProductRefId = "x" });
    var beforeAmbiguous = File.ReadAllBytes(freshPath);
    ExpectFailure(() => Knxproj.Save(ambiguous, freshPath), "ambiguous modeled identity refuses destructive save");
    Check(File.ReadAllBytes(freshPath).SequenceEqual(beforeAmbiguous), "ambiguous save leaves original identical");

    // R2 regression: a duplicate identity inside a newly added subtree reaches CopyAdded,
    // which never compared siblings. It must still be refused before the destination changes.
    var newSubtree = Knxproj.FromXml(XDocument.Parse(fixture));
    var subtreeArea = newSubtree.Installations[0].Areas[0];
    var duplicateLine = new Line { Id = "L-dup", Address = 3, Name = "Duplicate line" };
    // Same address and id twice: both are new, so no old sibling exists to compare against.
    subtreeArea.Lines.Add(duplicateLine);
    duplicateLine.Devices.Add(new DeviceInstance { Id = "1.1.9", ProductRefId = "P-9", Address = new IndividualAddress(1, 1, 9) });
    duplicateLine.Devices.Add(new DeviceInstance { Id = "1.1.9", ProductRefId = "P-9", Address = new IndividualAddress(1, 1, 9) });
    var beforeSubtree = File.ReadAllBytes(freshPath);
    ExpectFailure(() => Knxproj.Save(newSubtree, freshPath), "duplicate identity in added subtree refused");
    Check(File.ReadAllBytes(freshPath).SequenceEqual(beforeSubtree), "added-subtree refusal leaves original identical");
    var freshDuplicate = Path.Combine(directory, "fresh-duplicate.knxproj");
    ExpectFailure(() => Knxproj.Save(newSubtree, freshDuplicate), "fresh project duplicate identity refused");
    Check(!File.Exists(freshDuplicate), "refusal does not create a new destination");

    // R-G2: an archive without <Locations> receives one at the schema position on save
    // (Topology, Locations, GroupAddresses); an unmodeled installation child keeps its slot.
    {
        const string orderFixture = """
            <KNX xmlns="http://knx.org/xml/project/23" xmlns:v="urn:vendor">
              <MasterData Id="MD-1" Version="198"/>
              <Project Id="P-order" Name="Order">
                <Installations><Installation InstallationId="I-order" Name="House" Type="Regular">
                  <Topology/>
                  <v:Extra/>
                  <GroupAddresses><GroupRanges/></GroupAddresses>
                </Installation></Installations>
              </Project>
            </KNX>
            """;
        var sourcePath = Path.Combine(directory, "order-source.knxproj");
        File.WriteAllBytes(sourcePath, Zip(new() { ["0.xml"] = Encoding.UTF8.GetBytes(orderFixture) }));
        var orderProject = Knxproj.Load(sourcePath);
        orderProject.Installations[0].Locations.Add(null, "House", SpaceKind.Building, "SP-order");
        var savedPath = Path.Combine(directory, "order-saved.knxproj");
        Knxproj.Save(orderProject, savedPath);
        using var savedXml = new MemoryStream(Unzip(File.ReadAllBytes(savedPath))["0.xml"]);
        var savedDoc = XDocument.Load(savedXml);
        var installationChildren = string.Join(",",
            savedDoc.Descendants().Single(e => e.Name.LocalName == "Installation").Elements().Select(e => e.Name.LocalName));
        Check(installationChildren == "Topology,Extra,Locations,GroupAddresses", "new Locations inserted in schema order: " + installationChildren);
    }

    // Local backup/recovery independent of undo, layout and background timers.
    {
        Check(Path.IsPathFullyQualified(ProjectBackup.DefaultRootPath)
            && ProjectBackup.DefaultRootPath.Contains("BusChord", StringComparison.Ordinal),
            "default backup root is a local profile path: " + ProjectBackup.DefaultRootPath);
        var backupRoot = Path.Combine(directory, "backups");
        var backupSource = Path.Combine(directory, "backup-source.knxproj");
        var opaqueMember = new byte[] { 9, 8, 7, 0, 255, 42 };
        File.WriteAllBytes(backupSource, Zip(new()
        {
            ["0.xml"] = Encoding.UTF8.GetBytes(fixture),
            ["opaque/member.bin"] = opaqueMember,
            ["../never-extracted.txt"] = baggage,
        }));
        var backupBytes = File.ReadAllBytes(backupSource);
        var first = ProjectBackup.Create(backupSource, backupRoot);
        Check(File.Exists(first.BackupPath), "backup archive written");
        Check(first.Sha256 == Convert.ToHexString(SHA256.HashData(backupBytes)) && first.SizeBytes == backupBytes.Length,
            "backup manifest SHA-256 and size");
        Check(first.ProjectId == "P-1" && first.Name == "Original" && first.SourcePath == Path.GetFullPath(backupSource),
            "backup manifest project metadata");
        Check(ProjectBackup.List(backupSource, backupRoot).Single().Id == first.Id, "backup listed by project path");
        Check(ProjectBackup.List(null, backupRoot).Any(b => b.Id == first.Id), "backup listed by root");
        var renamedSource = Path.Combine(directory, "renamed.knxproj");
        File.Copy(backupSource, renamedSource);
        Check(ProjectBackup.List(renamedSource, backupRoot).Any(b => b.Id == first.Id),
            "backup follows the stored project GUID after rename");

        ProjectBackup.Create(backupSource, backupRoot, retention: 2);
        ProjectBackup.Create(backupSource, backupRoot, retention: 2);
        ProjectBackup.Create(backupSource, backupRoot, retention: 2);
        var retained = ProjectBackup.List(backupSource, backupRoot);
        Check(retained.Count == 2, "retention bounds backups per project");
        Check(Directory.GetFiles(backupRoot, "*.knxproj").Length == 2 && Directory.GetFiles(backupRoot, "*.json").Length == 2,
            "retention removes both archive and manifest");

        var restorePath = Path.Combine(directory, "restored.knxproj");
        ProjectBackup.Restore(retained[0].Id, restorePath, backupRoot);
        Check(File.ReadAllBytes(restorePath).SequenceEqual(File.ReadAllBytes(retained[0].BackupPath)),
            "restore copies archive bytes");
        Check(Unzip(File.ReadAllBytes(restorePath))["opaque/member.bin"].SequenceEqual(opaqueMember),
            "restore keeps opaque ZIP member");
        Check(Knxproj.Load(restorePath).Name == "Original", "restore output loads as project");
        Check(File.ReadAllBytes(backupSource).SequenceEqual(backupBytes), "restore elsewhere leaves original untouched");

        var modified = Knxproj.Load(backupSource);
        modified.Name = "Modified";
        Knxproj.Save(modified, backupSource);
        Check(!File.ReadAllBytes(backupSource).SequenceEqual(backupBytes), "source modified before in-place restore");
        ProjectBackup.Restore(retained[0].Id, backupSource, backupRoot);
        Check(File.ReadAllBytes(backupSource).SequenceEqual(File.ReadAllBytes(retained[0].BackupPath)),
            "in-place restore replaces original atomically");

        var corruptId = retained[0].Id;
        File.WriteAllBytes(Path.Combine(backupRoot, corruptId + ".knxproj"), Encoding.UTF8.GetBytes("not a zip"));
        var beforeFailedRestore = File.ReadAllBytes(restorePath);
        ExpectFailure(() => ProjectBackup.Restore(corruptId, restorePath, backupRoot), "corrupt backup rejected");
        Check(File.ReadAllBytes(restorePath).SequenceEqual(beforeFailedRestore),
            "failed restore preserves destination");
        Check(!Directory.EnumerateFiles(directory, "*.tmp").Any() &&
              !Directory.EnumerateFiles(backupRoot, "*.tmp").Any(), "failed restore cleans temporary files");

        foreach (var badId in new[] { "../escape", "..\\escape", "sub/dir", "bad:id", "" })
            ExpectFailure(() => ProjectBackup.Restore(badId, Path.Combine(directory, "escape.knxproj"), backupRoot),
                "backup ID traversal rejected");
        Check(!File.Exists(Path.Combine(directory, "escape.knxproj")), "rejected backup ID creates no file");
        ExpectFailure(() => ProjectBackup.Restore("missing", restorePath, backupRoot), "missing backup rejected");
        ExpectFailure(() => ProjectBackup.Restore(retained[1].Id, Path.Combine(backupRoot, "inside.knxproj"), backupRoot),
            "restore into backup root rejected");

        var empty = Path.Combine(directory, "empty.knxproj");
        File.WriteAllBytes(empty, []);
        ExpectFailure(() => ProjectBackup.Create(empty, backupRoot), "empty project archive rejected");
        var junk = Path.Combine(directory, "junk.knxproj");
        File.WriteAllBytes(junk, [1, 2, 3, 4]);
        ExpectFailure(() => ProjectBackup.Create(junk, backupRoot), "corrupt project archive rejected");
        var oversized = Path.Combine(directory, "oversized.knxproj");
        using (var stream = File.Create(oversized)) stream.SetLength(128L * 1024 * 1024 + 1);
        ExpectFailure(() => ProjectBackup.Create(oversized, backupRoot), "oversized project archive rejected");
        File.Delete(oversized);

        var capturedProject = Knxproj.Load(backupSource);
        capturedProject.Name = "Captured";
        var captured = ProjectBackup.Capture(capturedProject, backupSource, backupRoot, retention: 2);
        Check(ProjectBackup.List(backupSource, backupRoot).Any(b => b.Id == captured.Id && b.Name == "Captured"),
            "explicit capture listed");
        Check(Knxproj.Load(captured.BackupPath).Name == "Captured", "capture archive loads");
        ProjectBackup.Delete(captured.Id, backupRoot);
        Check(!File.Exists(captured.BackupPath) && !File.Exists(Path.ChangeExtension(captured.BackupPath, ".json")),
            "delete removes archive and manifest");
        ExpectFailure(() => ProjectBackup.Delete(captured.Id, backupRoot), "delete missing backup is explicit");
    }

    Native20ArchiveChecks.Run(directory, Check);
    Native22ArchiveChecks.Run(directory, Check);
    Console.WriteLine($"ALL {checks} ARCHIVE CHECKS PASSED");
}
finally
{
    Directory.Delete(directory, true);
}

void Check(bool condition, string name)
{
    if (!condition) throw new Exception("FAIL: " + name);
    checks++;
}

void ExpectFailure(Action action, string name)
{
    try { action(); }
    catch (Exception e) when (e is IOException or InvalidDataException or System.Xml.XmlException or ArgumentException or InvalidOperationException or NotSupportedException)
    { checks++; return; }
    throw new Exception("FAIL: expected refusal: " + name);
}

static DeviceInstance Device(Project project) => project.Installations[0].Areas[0].Lines[0].Devices[0];

static byte[] Zip(Dictionary<string, byte[]> entries)
{
    using var buffer = new MemoryStream();
    using (var zip = new ZipArchive(buffer, ZipArchiveMode.Create, true))
        foreach (var (name, bytes) in entries)
        {
            using var stream = zip.CreateEntry(name).Open();
            stream.Write(bytes);
        }
    return buffer.ToArray();
}

static Dictionary<string, byte[]> Unzip(byte[] bytes)
{
    using var buffer = new MemoryStream(bytes);
    using var zip = new ZipArchive(buffer, ZipArchiveMode.Read);
    return zip.Entries.ToDictionary(e => e.FullName, e =>
    {
        using var stream = e.Open();
        using var data = new MemoryStream();
        stream.CopyTo(data);
        return data.ToArray();
    });
}

static byte[] Encrypted(byte[] bytes)
{
    // Synthetic encrypted flags: rejection must happen before attempting decompression.
    for (int i = 0; i + 46 < bytes.Length; i++)
        if (bytes[i] == 0x50 && bytes[i + 1] == 0x4b && bytes[i + 2] == 1 && bytes[i + 3] == 2)
            bytes[i + 8] |= 1;
    return bytes;
}
